package com.openclassrooms.mddapi.mapper;

import org.mapstruct.Mapper;

import com.openclassrooms.mddapi.dto.TopicResponse;
import com.openclassrooms.mddapi.model.Topic;

/**
 * Converts {@link Topic} entities into API responses. The implementation is generated by MapStruct at compile time.
 */
@Mapper(componentModel = "spring")
public interface TopicMapper {

	/**
	 * Builds the API representation of a topic.
	 *
	 * @param topic the entity to convert
	 * @return the topic response
	 */
	TopicResponse toResponse(Topic topic);

}
